import collections
import json
import os
def task_func(directory_path: str) -> dict:
    counts = collections.Counter()
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                    if isinstance(data, dict):
                        for key in data.keys():
                            counts[key] += 1
                except (json.JSONDecodeError, IOError):
                    continue
    return dict(counts)

import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        data = json.load(f)

    for field in INPUT_JSON["required"]:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    for field, rules in INPUT_JSON["properties"].items():
        if field in data:
            if not isinstance(data[field], rules["type"]):
                raise ValueError(f"Type mismatch for {field}")

    if "email" in data and not re.match(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found in JSON")

    return data[attribute]

