import re
import json
import os
def task_func(file_path: str, regex_pattern=r'\(.+?\)|\w') -> dict:
    import re
    import json
    import os

    results = {}

    if os.path.isfile(file_path):
        files = [file_path]
    else:
        files = [os.path.join(file_path, f) for f in os.listdir(file_path) if f.endswith('.json')]

    for path in files:
        try:
            with open(path, 'r') as f:
                content = f.read()
                matches = re.findall(regex_pattern, content)
                results[os.path.basename(path)] = matches
        except (json.JSONDecodeError, IOError):
            continue

    return results

