import pandas as pd

def task_func(json_str):
    if not json_str:
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()

    processed_data = {}
    for key, value in data.items():
        if isinstance(value, (int, float)):
            processed_data[key] = float(value * 2)
        elif isinstance(value, list):
            processed_data[key] = [float(item * 2) if isinstance(item, (int, float)) else item for item in value]
        elif isinstance(value, str):
            def double_match(match):
                return str(float(match.group()) * 2)
            processed_data[key] = re.sub(r"[-+]?\d*\.\d+|\d+", double_match, value)
