import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    with open(input_file, 'r') as f:
        data = json.load(f)

    stats = defaultdict(list)
    for entry in data:
        for key, value in entry.items():
